fields.InputDefinition:
{
  "goal": "Open the 'Events' entity grid — type 'Events' in the LEFT sidebar 'Search entities...' box and click the exact 'Events' node (or, if the search is giving you trouble, navigate directly to http://localhost:4200/app/data-explorer/Data?entity=Events). Click a row, then click 'Open Full Record'. Find the 'Is Virtual' checkbox/toggle field and click it to flip its value (checked↔unchecked). An unsaved-changes banner with a 'Save Changes' button appears at the TOP — click 'Save Changes'. Verify the save succeeds with no error. Pages can take 10-30s to load — wait, don't navigate away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "minConfidence": 0.7,
  "maxSteps": 40,
  "judgeValidationCriteria": [
    "The 'Is Virtual' boolean field was toggled on an Event record",
    "Save Changes was clicked and the save succeeded with no error",
    "No error messages or crash pages"
  ]
}
